<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { X, Check, CheckCircle2, CircleAlert, LoaderCircle, Sparkles, ArrowLeft, RefreshCw, Plus, Upload, Download, ChevronLeft, ChevronRight, PencilLine } from 'lucide-vue-next'
import { api, type ReviewView, type ReviewRow, type Student, type ReviewIssue, type StudentField } from '../api'
import { refreshFields, typeLabels, fieldOptions } from '../field-state'
import FieldValueInput from './FieldValueInput.vue'
import BatchReportTable from './BatchReportTable.vue'
const props = defineProps<{ conversationId: string; reviewId: string }>()
const emit = defineEmits<{ close: []; updated: []; notify: [message: string, kind?: string] }>()
const draft = ref<ReviewView | null>(null), busy = ref(false), error = ref(''), mappingOpen = ref(false)
const mode = ref('UPSERT'), mappings = ref<Record<number, {target: string; label: string; type: string}>>({})
const cells = ref<Record<number, Record<number, string>>>({}), excluded = ref<number[]>([]), backfill = ref<Record<string, Record<string, unknown>>>({})
const page = ref(1), backfillPage = ref(1), filter = ref(''), pageSize = 20, sheetIndex = ref(0), headerRow = ref(1), hasHeader = ref('auto'), upload = ref<HTMLInputElement>()
const stageLabels: Record<string,string> = { MAPPING:'确认字段', ROWS:'修正记录', BACKFILL:'补全已有学生', SCHEMA_READY:'确认新增字段', READY:'最终核对', COMPLETE:'处理完成', CANCELLED:'已取消未执行操作' }
const modes = [{value:'CREATE',label:'新增'}, {value:'UPDATE',label:'更新'}, {value:'UPSERT',label:'新增或更新'}, {value:'DELETE',label:'删除'}, {value:'QUERY',label:'查询'}]
const shownRows = computed(() => draft.value?.rows.slice((page.value - 1) * pageSize, page.value * pageSize) || [])
const pages = computed(() => Math.max(1, Math.ceil((draft.value?.rows.length || 0) / pageSize)))
const filteredExisting = computed(() => draft.value?.existingStudents.filter(student => !filter.value || student.studentNo.includes(filter.value) || student.name.includes(filter.value)) || [])
const existingPages = computed(() => Math.max(1, Math.ceil(filteredExisting.value.length / pageSize)))
const shownExisting = computed(() => filteredExisting.value.slice((backfillPage.value - 1) * pageSize, backfillPage.value * pageSize))
const mappingVisible = computed(() => draft.value?.stage === 'MAPPING' || mappingOpen.value)
const isBackfill = computed(() => ['BACKFILL', 'SCHEMA_READY'].includes(draft.value?.stage || ''))
const completed = computed(() => ['COMPLETE','CANCELLED'].includes(draft.value?.stage || ''))
const closePrompt = ref(false)
const dialog = ref<HTMLElement>()
const unsaved = computed(() => {
  const view = draft.value; if (!view) return false
  if (mode.value !== view.mode) return true
  if (view.columns.some(column => { const choice = mappings.value[column.index]; return choice && (choice.target !== column.target || choice.target === 'NEW' && (choice.label !== column.newLabel || choice.type !== column.newType)) })) return true
  if (view.rows.some(row => excluded.value.includes(row.number) !== row.excluded || view.columns.some(column => (cells.value[row.number]?.[column.index] || '') !== (row.values[column.index] || '')))) return true
  return view.existingStudents.some(student => view.proposedFields.some(field => String(backfill.value[student.studentNo]?.[field.key] ?? '') !== String(view.backfill[student.studentNo]?.[field.key] ?? '')))
})
function requestClose() { if (!busy.value) { if (unsaved.value) closePrompt.value = true; else emit('close') } }
const activeCount = computed(() => (draft.value?.rows.length || 0) - excluded.value.length)
const issues = computed(() => draft.value?.issues.filter(issue => issue.code !== 'BACKFILL_INVALID').slice(0, 15) || [])
const backfillProblemCount = computed(() => draft.value?.issues.filter(issue => issue.code === 'BACKFILL_INVALID').length || 0)
const targetOptions = computed(() => [{key:'studentNo',label:'学号'}, {key:'name',label:'姓名'}, ...(mode.value === 'UPDATE' ? [{key:'newStudentNo',label:'新学号'}] : []), ...(draft.value?.fields || []).map(field => ({key:field.key,label:field.label}))])
function columnGenderField(index: number): StudentField | null {
  const choice = mappings.value[index]; if (!choice) return null
  const field = draft.value?.fields.find(field => field.key === choice.target) || (choice.target === 'NEW' ? {key:'new',label:choice.label,type:choice.type as StudentField['type'],required:true} : null)
  return field && fieldOptions(field).length ? field : null
}
function accept(view: ReviewView) {
  const changedStep = draft.value?.id !== view.id || draft.value?.stage !== view.stage
  draft.value = view; mode.value = view.mode; mappingOpen.value = false
  mappings.value = Object.fromEntries(view.columns.map(column => [column.index, {target:column.target,label:column.newLabel,type:column.newType}]))
  cells.value = Object.fromEntries(view.rows.map(row => [row.number,{...row.values}]))
  excluded.value = view.rows.filter(row => row.excluded).map(row => row.number)
  backfill.value = structuredClone(view.backfill); sheetIndex.value = view.sheetIndex; headerRow.value = view.headerRow || 1
  page.value = Math.min(page.value, Math.max(1, Math.ceil(view.rows.length / pageSize))); backfillPage.value = 1
  if (changedStep) void nextTick(() => dialog.value?.scrollTo({top:0}))
}
async function work(action: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; try { await action() } catch (ex) { error.value = ex instanceof Error ? ex.message : '处理失败，请重试' } finally { busy.value = false } }
async function load(id = props.reviewId) { await work(async () => accept(await api<ReviewView>(`/reviews/${id}?conversationId=${props.conversationId}`))) }
watch(() => props.reviewId, id => { void load(id) }, {immediate:true})
watch(filter, () => { backfillPage.value = 1 })
function payload(extra: Record<string,unknown> = {}) {
  const view = draft.value!; const edits: {row:number;column:number;value:string}[] = []
  for (const row of view.rows) for (const column of view.columns) if ((cells.value[row.number]?.[column.index] || '') !== (row.values[column.index] || '')) edits.push({row:row.number,column:column.index,value:cells.value[row.number]?.[column.index] || ''})
  return {revision:view.revision,mode:mode.value,cells:edits,excluded:excluded.value,backfill:view.proposedFields.length && view.existingStudents.length ? Object.entries(backfill.value).map(([studentNo, values]) => ({studentNo,values})) : undefined,...extra}
}
async function save(extra: Record<string,unknown> = {}) { await work(async () => { accept(await api<ReviewView>(`/reviews/${draft.value!.id}?conversationId=${props.conversationId}`, {method:'PATCH',body:JSON.stringify(payload(extra))})); emit('updated') }) }
async function confirmMapping() { await save({mappings:Object.entries(mappings.value).map(([column,choice]) => ({column:Number(column),...choice})),confirmMapping:true}) }
async function suggest() { await work(async () => accept(await api<ReviewView>(`/reviews/${draft.value!.id}/suggest`, {method:'POST',body:JSON.stringify({conversationId:props.conversationId,revision:draft.value!.revision})}))) }
async function reread() { await work(async () => accept(await api<ReviewView>(`/reviews/${draft.value!.id}/source`, {method:'POST',body:JSON.stringify({conversationId:props.conversationId,revision:draft.value!.revision,sheetIndex:sheetIndex.value,headerRow:headerRow.value,hasHeader:hasHeader.value === 'auto' ? null : hasHeader.value === 'yes'})}))) }
async function addColumn(target: string) { await save({addColumn:target}) }
function excludeProblems() { excluded.value = [...new Set([...excluded.value,...(draft.value?.rows.filter(row => row.issues.length).map(row => row.number) || [])])] }
function chooseCandidate(row: ReviewRow, value: string) {
  const candidate = row.candidates.find(student => student.studentNo === value); if (!candidate) return
  const idColumn = draft.value!.columns.find(column => mappings.value[column.index]?.target === 'studentNo')
  if (idColumn) cells.value[row.number]![idColumn.index] = candidate.studentNo
  const nameColumn = draft.value!.columns.find(column => mappings.value[column.index]?.target === 'name')
  if (nameColumn && (['DELETE','QUERY'].includes(mode.value) || !cells.value[row.number]![nameColumn.index])) cells.value[row.number]![nameColumn.index] = candidate.name
}
function useSuggestion(issue: ReviewIssue) { if (issue.row != null && issue.column != null && issue.suggestion != null) cells.value[issue.row]![issue.column] = issue.suggestion }
function invalidBackfill(student: Student, key: string) { return draft.value?.issues.some(issue => issue.code === 'BACKFILL_INVALID' && issue.choices[0] === student.studentNo && issue.choices[1] === key) }
async function confirmFields() { await work(async () => { accept(await api<ReviewView>(`/reviews/${draft.value!.id}/fields`, {method:'POST',body:JSON.stringify({conversationId:props.conversationId,revision:draft.value!.revision})})); await refreshFields(); emit('updated') }) }
async function finish() { await work(async () => { accept(await api<ReviewView>(`/reviews/${draft.value!.id}/finish`, {method:'POST',body:JSON.stringify({conversationId:props.conversationId,revision:draft.value!.revision})})); await refreshFields(); emit('updated'); emit('notify', draft.value!.message, draft.value!.result && !draft.value!.result.success ? 'error' : 'success') }) }
async function cancelDraft() { await work(async () => { accept(await api<ReviewView>(`/reviews/${draft.value!.id}/cancel`, {method:'POST',body:JSON.stringify({conversationId:props.conversationId,revision:draft.value!.revision})})); emit('updated') }) }
async function uploadBackfill(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return
  await work(async () => {
    if (file.size > 2 * 1024 * 1024) throw new Error('补全文件不能超过2MB')
    accept(await api<ReviewView>(`/reviews/${draft.value!.id}?conversationId=${props.conversationId}`, {method:'PATCH',body:JSON.stringify(payload())}))
    const form = new FormData(); form.append('conversationId',props.conversationId); form.append('file',file)
    accept(await api<ReviewView>(`/reviews/${draft.value!.id}/backfill`, {method:'POST',body:form}))
  })
  ;(event.target as HTMLInputElement).value = ''
}
async function retry() { await work(async () => { if (!draft.value?.result?.data || !('rows' in draft.value.result.data)) return; accept(await api<ReviewView>('/reviews/retry',{method:'POST',body:JSON.stringify({conversationId:props.conversationId,report:draft.value.result.data})})); emit('updated') }) }
const stageNumber = computed(() => draft.value?.stage === 'MAPPING' ? 1 : ['ROWS'].includes(draft.value?.stage || '') ? 2 : isBackfill.value ? 3 : completed.value ? 5 : 4)
</script>
<template>
  <div class="modal-backdrop review-backdrop" @mousedown.self="requestClose"><section ref="dialog" class="modal review-modal" role="dialog" aria-modal="true" aria-labelledby="review-title">
    <div class="review-heading"><div><span class="eyebrow">数据校对与确认</span><h2 id="review-title">{{ draft?.purpose === 'BACKFILL' ? '识别补全文件，再返回原草稿。' : '把问题处理清楚，再执行。' }}</h2></div><button class="icon-button" :disabled="busy" aria-label="关闭数据校对" @click="requestClose"><X :size="20" /></button></div>
    <div v-if="!draft" class="review-loading"><LoaderCircle class="spin" :size="24" />{{ error || '正在载入校对草稿…' }}</div>
    <template v-else>
      <div class="review-stages"><span v-for="(label,index) in ['字段对应','记录校对','已有数据补全','执行确认','完成']" :key="label" :class="{active:stageNumber === index + 1,passed:stageNumber > index + 1}"><b>{{ stageNumber > index + 1 ? '✓' : index + 1 }}</b>{{ label }}</span></div>
      <div class="review-status"><CheckCircle2 v-if="['READY','SCHEMA_READY','COMPLETE'].includes(draft.stage)" :size="19" /><CircleAlert v-else :size="19" /><div><strong>{{ stageLabels[draft.stage] }}</strong><p>{{ draft.message }}</p></div><span>{{ draft.rows.length }} 行</span></div>
      <div class="review-source-bar"><span>{{ draft.source }}</span><label v-if="!completed && draft.purpose !== 'BACKFILL'">本批操作<select v-model="mode" :disabled="busy"><option v-for="option in modes" :value="option.value" :key="option.value">{{ option.label }}</option></select></label><button v-if="draft.parentId" class="text-button" :disabled="busy" @click="load(draft.parentId)"><ArrowLeft :size="14" />返回原草稿</button><button v-if="!completed" class="text-button" :disabled="busy" @click="mappingOpen = !mappingOpen"><PencilLine :size="13" />调整字段对应</button></div>
      <details v-if="!completed && (draft.sheets.length || draft.source === '批量文本')" class="review-details"><summary>工作表或表头识别不准确？调整原始数据读取方式</summary><div class="review-source-controls"><template v-if="draft.sheets.length"><label>工作表<select v-model.number="sheetIndex"><option v-for="sheet in draft.sheets" :key="sheet.index" :value="sheet.index">{{ sheet.name }}</option></select></label><label>表头行号<input v-model.number="headerRow" type="number" min="1" /></label></template><label v-else>首行是表头<select v-model="hasHeader"><option value="auto">自动判断</option><option value="yes">是</option><option value="no">否</option></select></label><button class="button small" :disabled="busy" @click="reread"><RefreshCw :size="13" />按原始文件重新读取</button><small>重新读取会替换当前未保存的编辑。</small></div></details>
      <section v-if="mappingVisible && !completed" class="review-section"><div class="review-section-heading"><div><h3>这些列分别表示什么？</h3><p>建议仅供参考。每列都需要明确选择，重复含义的列不会自动合并，额外列不会自动忽略。</p></div><button class="button small" :disabled="busy" @click="suggest"><Sparkles :size="14" />请 DeepSeek 推测</button></div><div class="review-table-scroll"><table class="mapping-table"><thead><tr><th>原列名与样例</th><th>准确对应</th><th>建议与处理依据</th></tr></thead><tbody><tr v-for="column in draft.columns" :key="column.index"><td><strong>{{ column.index + 1 }}. {{ column.label }}</strong><small>{{ column.samples.join(' / ') || '无非空样例' }}</small></td><td><select v-model="mappings[column.index]!.target" :disabled="busy"><option value="UNDECIDED">请选择处理方式</option><option v-for="target in targetOptions" :key="target.key" :value="target.key">{{ target.label }}</option><option v-if="draft.purpose !== 'BACKFILL'" value="NEW">新增正式字段…</option><option value="IGNORE">明确忽略此列</option></select><div v-if="mappings[column.index]!.target === 'NEW'" class="new-field-inputs"><input v-model="mappings[column.index]!.label" placeholder="填写正式字段名称" maxlength="40" /><select v-model="mappings[column.index]!.type"><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select><small>需要补齐全部已有学生的值。</small></div></td><td><template v-for="(suggestion,index) in column.suggestions" :key="index"><button class="mapping-suggestion" :disabled="busy" @click="mappings[column.index]!.target = suggestion.target">{{ suggestion.source }}：{{ targetOptions.find(target => target.key === suggestion.target)?.label || suggestion.target }}</button><p class="suggestion-reason">{{ suggestion.reason }}</p></template><span v-if="!column.suggestions.length" class="muted">暂无可靠对应，请选择现有字段、新增或忽略。</span></td></tr></tbody></table></div><button class="button primary" :disabled="busy" @click="confirmMapping"><Check :size="15" />确认字段对应并校验</button></section>
      <div v-if="issues.length && !completed" class="review-issues"><strong>仍需处理的问题</strong><div v-for="(issue,index) in issues" :key="index"><CircleAlert :size="13" /><span>{{ issue.row ? `第${issue.row}行：` : '' }}{{ issue.message }}</span><button v-if="['MISSING_COLUMN','MISSING_FIELD'].includes(issue.code) && issue.suggestion" class="text-button" :disabled="busy" @click="addColumn(issue.suggestion!)"><Plus :size="12" />添加补全列</button><button v-if="issue.row != null && issue.column != null && issue.suggestion && !['MISSING_COLUMN','MISSING_FIELD'].includes(issue.code)" class="text-button" @click="useSuggestion(issue)">采用建议值：{{ issue.suggestion }}</button><template v-if="issue.choices.some(choice => ['CREATE','UPDATE','UPSERT'].includes(choice))"><button v-for="choice in issue.choices.filter(choice => ['CREATE','UPDATE','UPSERT'].includes(choice))" :key="choice" class="text-button" :disabled="busy" @click="mode = choice; save()">本批改为{{ modes.find(option => option.value === choice)?.label }}</button></template></div><small v-if="draft.issues.length > issues.length && !isBackfill">其余问题请查看逐行说明。</small></div>
      <section v-if="!completed && !isBackfill" class="review-section"><div class="review-section-heading"><div><h3>{{ draft.stage === 'MAPPING' ? '原始记录预览' : '直接修正记录' }}</h3><p>保留原始值供核对。编辑、采用候选或排除行后，需要再次校验。</p></div><div class="review-row-tools"><button v-if="draft.rows.some(row => row.issues.length)" class="button small" :disabled="busy" @click="excludeProblems">排除问题行</button><button v-if="draft.issues.some(issue => issue.code === 'DUPLICATE_ID')" class="button small" :disabled="busy" @click="save({action:'KEEP_FIRST_DUPLICATE'})">重复学号仅保留第一行</button></div></div><div class="review-table-scroll"><table class="review-data-table"><thead><tr><th>排除</th><th>原行号</th><th v-for="column in draft.columns" :key="column.index">{{ column.label }}<small>{{ targetOptions.find(target => target.key === mappings[column.index]?.target)?.label || (mappings[column.index]?.target === 'NEW' ? mappings[column.index]?.label : mappings[column.index]?.target === 'IGNORE' ? '已选择忽略' : '待确认') }}</small></th><th>问题与候选</th></tr></thead><tbody><tr v-for="row in shownRows" :key="row.number" :class="{excluded:excluded.includes(row.number)}"><td><input v-model="excluded" type="checkbox" :value="row.number" :disabled="busy || draft.stage === 'MAPPING'" :aria-label="`排除第${row.number}行`" /></td><td>{{ row.number }}</td><td v-for="column in draft.columns" :key="column.index"><FieldValueInput v-if="columnGenderField(column.index)" :field="columnGenderField(column.index)!" :model-value="cells[row.number]![column.index]" :disabled="busy || excluded.includes(row.number) || draft.stage === 'MAPPING'" :invalid="row.issues.some(issue => issue.column === column.index)" @update:model-value="value => cells[row.number]![column.index] = value" /><input v-else v-model="cells[row.number]![column.index]" :aria-label="`第${row.number}行${column.label}`" :disabled="busy || excluded.includes(row.number) || draft.stage === 'MAPPING'" :class="{invalid:row.issues.some(issue => issue.column === column.index)}" /></td><td class="review-row-issues"><span v-if="excluded.includes(row.number)">用户已选择排除</span><template v-else><p v-for="(issue,index) in row.issues" :key="index">{{ issue.message }}<button v-if="issue.suggestion && issue.column != null && !['MISSING_FIELD','MISSING_COLUMN'].includes(issue.code)" class="text-button" @click="useSuggestion(issue)">采用：{{ issue.suggestion }}</button></p><select v-if="row.candidates.length" :disabled="busy" @change="chooseCandidate(row,($event.target as HTMLSelectElement).value)"><option value="">请选择准确的学生（{{ row.candidates.length }}个候选）</option><option v-for="student in row.candidates" :key="student.studentNo" :value="student.studentNo">{{ student.studentNo }} · {{ student.name }}</option></select><span v-if="!row.issues.length">校验通过，修改后需重新校验</span></template></td></tr></tbody></table></div><div class="review-pager"><span>有效 {{ activeCount }} 行 · 已选择排除 {{ excluded.length }} 行</span><div><button class="icon-button" :disabled="page <= 1" @click="page--"><ChevronLeft :size="16" /></button><span>{{ page }} / {{ pages }}</span><button class="icon-button" :disabled="page >= pages" @click="page++"><ChevronRight :size="16" /></button></div></div><button v-if="draft.stage !== 'MAPPING'" class="button" :disabled="busy" @click="save()"><RefreshCw :size="14" />保存修正并重新校验</button></section>
      <section v-if="isBackfill" class="review-section"><div class="review-section-heading"><div><h3>为全部已有学生补齐新字段</h3><p>{{ draft.existingStudents.length }} 名已有学生，{{ draft.proposedFields.length }} 个待新增字段。未补齐或类型不正确时不能新增。</p></div><button class="button small" :disabled="busy" @click="save({action:'REFRESH_BACKFILL'})"><RefreshCw :size="13" />刷新已有名单</button></div><div class="review-backfill-tools"><input v-model="filter" class="form-input" placeholder="按学号或姓名筛选补全表" /><a class="button small" :href="`/api/reviews/${draft.id}/backfill-template?conversationId=${conversationId}`" download><Download :size="14" />下载已有学生补全表</a><button class="button small" :disabled="busy" @click="upload?.click()"><Upload :size="14" />上传Excel识别补全</button><input ref="upload" type="file" accept=".xlsx,.xls" hidden @change="uploadBackfill" /></div><div v-if="backfillProblemCount" class="review-backfill-warning">还有 {{ backfillProblemCount }} 个值未通过校验。填写后点击“保存补全值并校验”。</div><div class="review-table-scroll"><table class="review-data-table"><thead><tr><th>学号</th><th>姓名</th><th v-for="field in draft.proposedFields" :key="field.key">{{ field.label }}<small>{{ typeLabels[field.type] }} · 必须补齐</small></th></tr></thead><tbody><tr v-for="student in shownExisting" :key="student.studentNo"><td><code>{{ student.studentNo }}</code></td><td>{{ student.name }}</td><td v-for="field in draft.proposedFields" :key="field.key"><FieldValueInput :field="field" :model-value="backfill[student.studentNo]?.[field.key]" :invalid="invalidBackfill(student,field.key)" :disabled="busy" @update:model-value="value => (backfill[student.studentNo] ||= {})[field.key] = value" /><small v-for="issue in draft.issues.filter(issue => issue.code === 'BACKFILL_INVALID' && issue.choices[0] === student.studentNo && issue.choices[1] === field.key)" :key="issue.message" class="field-error">{{ issue.message }}</small></td></tr></tbody></table></div><div class="review-pager"><span>当前筛选 {{ filteredExisting.length }} 人</span><div><button class="icon-button" :disabled="backfillPage <= 1" @click="backfillPage--"><ChevronLeft :size="16" /></button><span>{{ backfillPage }} / {{ existingPages }}</span><button class="icon-button" :disabled="backfillPage >= existingPages" @click="backfillPage++"><ChevronRight :size="16" /></button></div></div><button class="button" :disabled="busy" @click="save()"><Check :size="14" />保存补全值并校验</button></section>
      <section v-if="draft.stage === 'READY' && draft.preview" class="review-section"><h3>最终执行预览</h3><BatchReportTable :report="draft.preview" /></section>
      <section v-if="completed && draft.result" class="review-section"><h3>{{ draft.result.message }}</h3><BatchReportTable v-if="draft.result.data && 'rows' in draft.result.data" :report="draft.result.data" /><button v-if="!draft.result.success" class="button" :disabled="busy" @click="retry"><PencilLine :size="14" />仅修正本次失败记录</button></section>
      <details v-if="draft.notes.length" class="review-details review-notes"><summary>处理依据与已确认事项（{{ draft.notes.length }}项）</summary><ol><li v-for="(note,index) in draft.notes" :key="index">{{ note }}</li></ol></details>
      <p v-if="error" class="form-error" role="alert"><CircleAlert :size="15" />{{ error }}<button class="text-button" :disabled="busy" @click="load(draft.id)">重新载入草稿</button></p>
      <p v-if="unsaved" class="review-unsaved">存在尚未校验的修改，请保存并重新校验后再确认执行。</p><div class="review-footer"><span><LoaderCircle v-if="busy" class="spin" :size="15" />{{ busy ? '正在处理，请等待…' : '草稿保留1小时；未确认的学生操作不会执行。' }}</span><div><button v-if="!completed" class="button" :disabled="busy" @click="cancelDraft">取消本次未执行操作</button><button class="button" :disabled="busy" @click="requestClose">{{ completed ? '完成并关闭' : '稍后处理' }}</button><button v-if="draft.stage === 'SCHEMA_READY'" class="button primary" :disabled="busy || unsaved" @click="confirmFields"><Check :size="15" />确认新增字段并保存全员补全值</button><button v-if="draft.stage === 'READY'" class="button" :class="mode === 'DELETE' ? 'danger' : 'primary'" :disabled="busy || unsaved" @click="finish"><Check :size="15" />{{ draft.purpose === 'BACKFILL' ? '确认应用到已有学生补全表' : mode === 'QUERY' ? '确认查询' : '确认执行本次操作' }}</button></div></div>
    </template>
    <div v-if="closePrompt" class="review-exit-overlay"><div class="review-exit-prompt"><h3>当前修改尚未保存</h3><p>继续编辑并重新校验可保存草稿。关闭只会保留上次已保存的内容。</p><div><button class="button" @click="closePrompt = false">继续编辑</button><button class="button" @click="emit('close')">放弃未保存修改并关闭</button></div></div></div>
  </section></div>
</template>
